    def create_form_fields(self, data, layout, prefix='',styleSheet = "color: black;"):
        for key, value in data.items():
            if isinstance(value, dict):
                self.create_form_fields(value, layout, prefix=prefix + '.' + key)
            else:
                label = QLabel(key.replace('_', ' ').capitalize())
                if key == "Motor_3" or key == "Motor_4":
                    label.setStyleSheet("color: red;")
                else:
                    label.setStyleSheet(styleSheet)

                field = QLineEdit(str(value))

                # Create a horizontal layout to hold the field and the unit label
                unit_label = QLabel(self.get_unit(key))  # Get the unit based on the key
                h_layout = QHBoxLayout()
                h_layout.addWidget(field)
                h_layout.addWidget(unit_label)

                layout.addRow(label, h_layout)
                self.fields[prefix + '.' + key] = field


    def get_unit(self, key):
        units = {
            "inner_radius": "cm",
            "max_deflection": "°",
            "min_deflection": "°",
            "outer_radius": "cm",
            "phi_dir": "steps/°",
            "radial_dir": "steps/cm",
            "speed": "Hz",
            "stop_time": "s",
            "Angular_mot_speed": "Hz",
            "Radial_mot_speed": "Hz",
            "Delay_time": "s"
        }
        return units.get(key, "")

    def save_yaml(self):
        for key, field in self.fields.items():
            keys = key.split('.')
            d = self.data
            for k in keys[:-1]:
                d = d.setdefault(k, {})
            d[keys[-1]] = self.convert_type(field.text())

        with open(yaml_file, 'w') as file:
            yaml.safe_dump(self.data, file)


    def save_and_close(self):
        # Save the data
        self.save_yaml()

        # Close the window after saving
        self.Configuration.close()

    def convert_type(self, value):
        try:
            if '.' in value:
                return float(value)
            else:
                return int(value)
        except ValueError:
            return value

